<script setup lang="ts">
import { X } from '@lucide/vue'
defineProps<{open:boolean;user:Record<string,any>|null;cards:any[];selectedCardId:string;loading:boolean;saving:boolean;errorMessage:string}>()
defineEmits<{close:[];save:[];cancelMembership:[];'update:selectedCardId':[value:string]}>()
</script>
<template><div v-if="open" class="drawer-backdrop-v2"><aside class="form-drawer-v2 business-drawer membership-assignment-drawer" role="dialog" aria-modal="true" aria-label="终端用户会员管理"><header class="drawer-header"><div><span class="eyebrow">Membership assignment</span><h2>{{user?.displayName||user?.username}}的会员权益</h2></div><button class="icon-button" :disabled="saving" aria-label="关闭" @click="$emit('close')"><X :size="18"/></button></header><div class="drawer-body"><div class="member-identity-note"><strong>当前会员</strong><span>{{user?.membershipName||user?.membership?.cardName||'免费会员'}}；重新分配后新权益立即生效。</span></div><section class="form-section"><h3>选择会员卡</h3><p>列表只提供当前组织可用且已启用的会员卡。</p><div v-if="loading" class="table-loading">正在加载会员卡…</div><div v-else class="selection-list membership-selection-list"><label v-for="item in cards.filter(card=>card.status==='enabled')" :key="item.id"><input type="radio" name="membership-card" :value="item.id" :checked="selectedCardId===item.id" @change="$emit('update:selectedCardId',item.id)"/><span><strong>{{item.name}}</strong><small>等级 {{item.level}} · {{item.package?.durationDays===0?'永久':`${item.package?.durationDays||0} 天`}}</small></span></label><p v-if="!cards.some(card=>card.status==='enabled')" class="muted-empty">暂无可分配会员卡</p></div></section><p v-if="errorMessage" class="drawer-error" role="alert">{{errorMessage}}</p></div><footer class="drawer-footer membership-assignment-footer"><button class="link-danger" :disabled="loading||saving" @click="$emit('cancelMembership')">取消当前会员并恢复免费会员</button><button class="primary-button" :disabled="loading||saving||!selectedCardId" @click="$emit('save')">{{saving?'处理中…':'分配会员卡'}}</button></footer></aside></div></template>
